CREATE TABLE IF NOT EXISTS cloud_settings (team_id VARCHAR(36) PRIMARY KEY, paused_retention_days INT NULL, failed_workspace_retention_days INT NOT NULL, max_running_sessions_per_member INT NOT NULL, max_retained_sessions_per_member INT NOT NULL, CONSTRAINT cloud_settings_team FOREIGN KEY (team_id) REFERENCES teams(id));
CREATE TABLE IF NOT EXISTS cloud_clusters (id VARCHAR(36) PRIMARY KEY, team_id VARCHAR(36) NOT NULL, `name` VARCHAR(120) NOT NULL, api_url VARCHAR(512) NOT NULL, ca_certificate text NOT NULL, credential text NOT NULL, allowed_namespaces text NOT NULL, max_running_pods INT NOT NULL, default_storage_class VARCHAR(253) NULL, version INT NOT NULL, orphaned_volumes INT DEFAULT 0 NOT NULL, last_gc_at BIGINT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, CONSTRAINT cloud_clusters_team FOREIGN KEY (team_id) REFERENCES teams(id));
ALTER TABLE cloud_clusters ADD CONSTRAINT cloud_cluster_name UNIQUE (team_id, `name`);
CREATE TABLE IF NOT EXISTS cloud_profiles (id VARCHAR(36) PRIMARY KEY, team_id VARCHAR(36) NOT NULL, `name` VARCHAR(120) NOT NULL, current_version INT NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, CONSTRAINT cloud_profiles_team FOREIGN KEY (team_id) REFERENCES teams(id));
ALTER TABLE cloud_profiles ADD CONSTRAINT cloud_profile_name UNIQUE (team_id, `name`);
CREATE TABLE IF NOT EXISTS cloud_profile_versions (profile_id VARCHAR(36), version INT, spec text NOT NULL, created_by VARCHAR(36) NOT NULL, created_at BIGINT NOT NULL, CONSTRAINT pk_cloud_profile_versions PRIMARY KEY (profile_id, version), CONSTRAINT cloud_profile_versions_profile FOREIGN KEY (profile_id) REFERENCES cloud_profiles(id));
CREATE TABLE IF NOT EXISTS cloud_profile_assignments (profile_id VARCHAR(36), member_id VARCHAR(36), CONSTRAINT pk_cloud_profile_assignments PRIMARY KEY (profile_id, member_id), CONSTRAINT cloud_profile_assignments_profile FOREIGN KEY (profile_id) REFERENCES cloud_profiles(id) ON DELETE CASCADE, CONSTRAINT cloud_profile_assignments_member FOREIGN KEY (member_id) REFERENCES members(id) ON DELETE CASCADE);
CREATE INDEX cloud_assignment_member ON cloud_profile_assignments (member_id);
CREATE TABLE IF NOT EXISTS cloud_sessions (id VARCHAR(36) PRIMARY KEY, team_id VARCHAR(36) NOT NULL, owner_id VARCHAR(36) NOT NULL, `name` VARCHAR(120) NOT NULL, initiator_id VARCHAR(36) NOT NULL, credential_id VARCHAR(36) NOT NULL, effective_member_id VARCHAR(36) NOT NULL, profile_id VARCHAR(36) NOT NULL, profile_version INT NOT NULL, cluster_id VARCHAR(36) NOT NULL, namespace VARCHAR(63) NOT NULL, image_reference VARCHAR(512) NOT NULL, image_digest VARCHAR(100) NULL, agent_kind VARCHAR(16) NOT NULL, agent_version VARCHAR(64) NULL, agent_model VARCHAR(120) NULL, agent_effort VARCHAR(120) NULL, `state` VARCHAR(16) NOT NULL, phase VARCHAR(64) NULL, desired_state VARCHAR(16) NOT NULL, generation BIGINT NOT NULL, current_epoch INT NOT NULL, idle_timeout_minutes INT NOT NULL, last_activity_at BIGINT NOT NULL, resume_workspace VARCHAR(20) NOT NULL, resume_conversation VARCHAR(20) NOT NULL, failure_code VARCHAR(64) NULL, failure_message VARCHAR(512) NULL, failure_retryable BOOLEAN DEFAULT FALSE NOT NULL, blocked_code VARCHAR(64) NULL, blocked_message VARCHAR(512) NULL, blocked_retryable BOOLEAN DEFAULT FALSE NOT NULL, pause_requested_at BIGINT NULL, pause_force BOOLEAN DEFAULT FALSE NOT NULL, paused_at BIGINT NULL, expires_at BIGINT NULL, terminated_reason VARCHAR(32) NULL, waiting_since BIGINT NULL, claim_name VARCHAR(63) NOT NULL, storage_class VARCHAR(253) NULL, workspace_size_gib INT NOT NULL, volume_name VARCHAR(253) NULL, volume_handle VARCHAR(512) NULL, deletion_state VARCHAR(16) NOT NULL, claim_deleted_at BIGINT NULL, volume_deleted_at BIGINT NULL, deletion_code VARCHAR(64) NULL, deletion_message VARCHAR(512) NULL, reconcile_owner VARCHAR(36) NULL, reconcile_until BIGINT DEFAULT 0 NOT NULL, reconcile_after BIGINT NULL, reconcile_requested BOOLEAN DEFAULT FALSE NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, CONSTRAINT cloud_sessions_team FOREIGN KEY (team_id) REFERENCES teams(id), CONSTRAINT cloud_sessions_owner FOREIGN KEY (owner_id) REFERENCES members(id), CONSTRAINT cloud_sessions_profile FOREIGN KEY (profile_id) REFERENCES cloud_profiles(id), CONSTRAINT cloud_sessions_cluster FOREIGN KEY (cluster_id) REFERENCES cloud_clusters(id));
CREATE INDEX cloud_session_owner ON cloud_sessions (team_id, owner_id, created_at);
CREATE INDEX cloud_session_team ON cloud_sessions (team_id, created_at);
CREATE INDEX cloud_session_due ON cloud_sessions (reconcile_after);
CREATE INDEX cloud_session_cluster_waiting ON cloud_sessions (cluster_id, waiting_since);
CREATE TABLE IF NOT EXISTS cloud_session_labels (session_id VARCHAR(36), label_key VARCHAR(63), label_value VARCHAR(256) NOT NULL, CONSTRAINT pk_cloud_session_labels PRIMARY KEY (session_id, label_key), CONSTRAINT cloud_session_labels_session FOREIGN KEY (session_id) REFERENCES cloud_sessions(id) ON DELETE CASCADE);
CREATE INDEX cloud_label_lookup ON cloud_session_labels (label_key, label_value);
CREATE TABLE IF NOT EXISTS cloud_executions (session_id VARCHAR(36), epoch INT, pod_name VARCHAR(63) NOT NULL, `state` VARCHAR(16) NOT NULL, created_at BIGINT NOT NULL, registered_at BIGINT NULL, last_heartbeat_at BIGINT NULL, runner_ready BOOLEAN DEFAULT FALSE NOT NULL, node_name VARCHAR(253) NULL, image_digest VARCHAR(100) NULL, ended_at BIGINT NULL, exit_reason VARCHAR(64) NULL, checkpoint VARCHAR(16) NULL, CONSTRAINT pk_cloud_executions PRIMARY KEY (session_id, epoch), CONSTRAINT cloud_executions_session FOREIGN KEY (session_id) REFERENCES cloud_sessions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS cloud_idempotency (team_id VARCHAR(36), initiator_id VARCHAR(36), route VARCHAR(120), idempotency_key VARCHAR(128) COLLATE ascii_bin, request_digest CHAR(64) NOT NULL, session_id VARCHAR(36) NOT NULL, created_at BIGINT NOT NULL, expires_at BIGINT NOT NULL, CONSTRAINT pk_cloud_idempotency PRIMARY KEY (team_id, initiator_id, route, idempotency_key), CONSTRAINT cloud_idempotency_team FOREIGN KEY (team_id) REFERENCES teams(id));
CREATE INDEX cloud_idempotency_expiry ON cloud_idempotency (expires_at);
